#!/usr/bin/perl
use strict;
use warnings;
use IO::Socket::SSL;
use IO::Select;

my $url = "https://go.dev/dl/go1.24.2.linux-arm64.tar.gz";
my ($host, $path) = ("go.dev", "/dl/go1.24.2.linux-arm64.tar.gz");

my $sock = IO::Socket::SSL->new(
    PeerHost => $host,
    PeerPort => 443,
    SSL_verify_mode => SSL_VERIFY_NONE,
) or die "SSL connect failed: $! $@";

print $sock "GET $path HTTP/1.1\r\nHost: $host\r\nConnection: close\r\n\r\n";

open my $out, '>', '/tmp/go.tar.gz' or die $!;
my $header = 1;
while (<$sock>) {
    if ($header) {
        $header = 0 if /^\r?$/;
        next;
    }
    print $out $_;
}
close $out;
close $sock;

my $size = -s '/tmp/go.tar.gz';
print "Downloaded $size bytes\n";
PERLEOF
perl /tmp/download_go.pl 2>&1

