args.command:
export PATH="/home/bench/go-install/go/bin:$PATH" && cd /tmp && cat > fanin_analyzer.go << 'GOEOF'
package main

import (
	"fmt"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

type declKey struct {
	pkgPath  string
	name     string // for methods: "(*Type).Method" or "(Type).Method"
	file     string
	line     int
}

type callStat struct {
	key            declKey
	totalSites     int
	distinctCallers map[string]struct{}
	prodSites      int
	distinctProd   map[string]struct{}
	callDetails    []string // for debugging top candidates
}

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedTypes | packages.NeedTypesInfo |
			packages.NeedSyntax | packages.NeedModule,
		Dir:  "/bench/repo",
	}

	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}
	if packages.PrintErrors(pkgs) > 0 {
		// continue with partial results
	}

	modulePath := "github.com/usememos/memos"
	stats := make(map[string]*callStat) // keyed by obj string

	getStat := func(obj types.Object) *callStat {
		if obj == nil || obj.Pkg() == nil {
			return nil
		}
		pkgPath := obj.Pkg().Path()
		if !strings.HasPrefix(pkgPath, modulePath+"/internal/") && pkgPath != modulePath+"/internal" {
			return nil
		}
		pos := obj.Pos()
		fset := token.NewFileSet()
		// find file/line from any package that owns the object
		var file string
		var line int
		for _, p := range pkgs {
			if p.Fset != nil {
				fset = p.Fset
			}
			if pos != token.NoPos {
				file = fset.File(pos).Name()
				line = fset.File(pos).Line(pos)
			}
		}
		name := obj.Name()
		if sig, ok := obj.Type().(*types.Signature); ok && sig.Recv() != nil {
			recv := sig.Recv().Type()
			name = types.TypeString(recv, nil) + "." + name
		}
		key := declKey{pkgPath: pkgPath, name: name, file: file, line: line}
		id := pkgPath + "|" + name
		if s, ok := stats[id]; ok {
			return s
		}
		s := &callStat{
			key:             key,
			distinctCallers: make(map[string]struct{}),
			distinctProd:    make(map[string]struct{}),
		}
		stats[id] = s
		return s
	}

	callerID := func(fn *types.Func) string {
		if fn == nil {
			return "<unknown>"
		}
		pkg := fn.Pkg()
		pkgName := ""
		if pkg != nil {
			pkgName = pkg.Path()
		}
		name := fn.Name()
		if sig, ok := fn.Type().(*types.Signature); ok && sig.Recv() != nil {
			recv := sig.Recv().Type()
			name = types.TypeString(recv, nil) + "." + name
		}
		return pkgName + "::" + name
	}

	isTestFile := func(filename string) bool {
		base := filepath.Base(filename)
		return strings.HasSuffix(base, "_test.go")
	}

	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 && pkg.Types == nil {
			continue
		}
		for _, syntax := range pkg.Syntax {
			var filePath string
			if pkg.Fset != nil && syntax != nil && len(syntax) > 0 {
				filePath = pkg.Fset.File(syntax.Pos()).Name()
			}
			isTest := isTestFile(filePath)

			// Walk using TypesInfo if available
			if pkg.TypesInfo == nil {
				continue
			}
			for pos, call := range pkg.TypesInfo.Calls {
				var callee types.Object
				switch c := call.(type) {
				case *types.Builtin:
					continue
				case *types.Func:
					callee = c
				default:
					continue
				}
				stat := getStat(callee)
				if stat == nil {
					continue
				}

				// find caller function
				var callerFn *types.Func
				callerPos := pkg.Fset.Position(pos)
				callerFile := callerPos.Filename
				callerIsTest := isTestFile(callerFile)

				// Walk scopes to find enclosing function
				for _, obj := range pkg.TypesInfo.Defs {
					if fn, ok := obj.(*types.Func); ok {
						if fn.Pos() <= pos && pos <= fn.End() {
							if callerFn == nil || fn.Pos() > callerFn.Pos() {
								callerFn = fn
							}
						}
					}
				}
				// Better: use Uses at enclosing scope
				if callerFn == nil {
					// search all funcs in package
					scope := pkg.Types.Scope()
					for _, name := range scope.Names() {
						obj := scope.Lookup(name)
						if fn, ok := obj.(*types.Func); ok {
							if fn.Pos() <= pos && pos <= fn.End() {
								if callerFn == nil || fn.Pos() > callerFn.Pos() {
									callerFn = fn
								}
							}
						}
					}
				}

				cid := callerID(callerFn)
				stat.totalSites++
				stat.distinctCallers[cid] = struct{}{}
				if !callerIsTest {
					stat.prodSites++
					stat.distinctProd[cid] = struct{}{}
				}
			}
		}
	}

	type result struct {
		id string
		*callStat
	}
	var results []result
	for id, s := range stats {
		results = append(results, result{id, s})
	}
	sort.Slice(results, func(i, j int) bool {
		if results[i].totalSites != results[j].totalSites {
			return results[i].totalSites > results[j].totalSites
		}
		return results[i].id < results[j].id
	})

	fmt.Println("=== TOP 25 BY TOTAL STATIC CALL SITES (all Go, including tests) ===")
	fmt.Printf("%-6s %-8s %-8s %-60s %s\n", "Rank", "Sites", "Callers", "Declaration", "Location")
	for i, r := range results {
		if i >= 25 {
			break
		}
		rel, _ := filepath.Rel("/bench/repo", r.key.file)
		fmt.Printf("%-6d %-8d %-8d %-60s %s:%d\n", i+1, r.totalSites, len(r.distinctCallers), r.key.pkgPath+"."+r.key.name, rel, r.key.line)
	}

	fmt.Println("\n=== TOP 25 BY PRODUCTION (non-_test.go) CALL SITES ===")
	sort.Slice(results, func(i, j int) bool {
		if results[i].prodSites != results[j].prodSites {
			return results[i].prodSites > results[j].prodSites
		}
		return results[i].id < results[j].id
	})
	fmt.Printf("%-6s %-8s %-8s %-60s %s\n", "Rank", "Sites", "Callers", "Declaration", "Location")
	for i, r := range results {
		if i >= 25 {
			break
		}
		rel, _ := filepath.Rel("/bench/repo", r.key.file)
		fmt.Printf("%-6d %-8d %-8d %-60s %s:%d\n", i+1, r.prodSites, len(r.distinctProd), r.key.pkgPath+"."+r.key.name, rel, r.key.line)
	}

	if len(results) > 0 {
		// re-sort by total for winner details
		sort.Slice(results, func(i, j int) bool {
			return results[i].totalSites > results[j].totalSites
		})
		w := results[0]
		fmt.Println("\n=== WINNER DETAILS ===")
		fmt.Printf("Function: %s.%s\n", w.key.pkgPath, w.key.name)
		rel, _ := filepath.Rel("/bench/repo", w.key.file)
		fmt.Printf("Location: %s:%d\n", rel, w.key.line)
		fmt.Printf("Total call sites: %d\n", w.totalSites)
		fmt.Printf("Distinct calling functions: %d\n", len(w.distinctCallers))
		fmt.Printf("Production call sites: %d\n", w.prodSites)
		fmt.Printf("Distinct production callers: %d\n", len(w.distinctProd))
		fmt.Printf("Total internal declarations analyzed: %d\n", len(results))
	}
}
GOEOF
go mod init fanin && go get golang.org/x/tools/go/packages@latest && go run fanin_analyzer.go 2>&1

