	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

const repoRoot = "/bench/repo"
const modulePath = "github.com/usememos/memos"

type declInfo struct {
	pkgPath string
	name    string // FuncName or "RecvType.MethodName"
	file    string
	line    int
}

type callStat struct {
	info           declInfo
	totalSites     int
	prodSites      int
	distinctAll    map[string]struct{}
	distinctProd   map[string]struct{}
	seenPositions  map[string]struct{} // dedupe file:line:col
}

func isInternalDecl(obj types.Object) bool {
	if obj == nil || obj.Pkg() == nil {
		return false
	}
	pkgPath := obj.Pkg().Path()
	return strings.HasPrefix(pkgPath, modulePath+"/internal/")
}

func objDisplayName(obj types.Object) string {
	name := obj.Name()
	if fn, ok := obj.(*types.Func); ok {
		if sig, ok := fn.Type().(*types.Signature); ok && sig.Recv() != nil {
			recv := sig.Recv().Type()
			// Use local type name when possible.
			if named, ok := recv.(*types.Named); ok && named.Obj() != nil && named.Obj().Pkg() == obj.Pkg() {
				return "*" + named.Obj().Name() + "." + name
			}
			if ptr, ok := recv.(*types.Pointer); ok {
				if named, ok := ptr.Elem().(*types.Named); ok && named.Obj() != nil && named.Obj().Pkg() == obj.Pkg() {
					return "*" + named.Obj().Name() + "." + name
				}
			}
			return types.TypeString(recv, func(p *types.Package) string { return p.Name() }) + "." + name
		}
	}
	return name
}

func callerKey(fn *types.Func) string {
	if fn == nil {
		return "<package-init>"
	}
	pkg := ""
	if fn.Pkg() != nil {
		pkg = fn.Pkg().Path()
	}
	return pkg + "::" + objDisplayName(fn)
}

func isTestFile(path string) bool {
	return strings.HasSuffix(filepath.Base(path), "_test.go")
}

func relRepo(path string) string {
	rel, err := filepath.Rel(repoRoot, path)
	if err != nil {
		return path
	}
	return rel
}

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedTypes | packages.NeedTypesInfo |
			packages.NeedSyntax | packages.NeedModule,
		Dir:   repoRoot,
		Tests: true,
	}

	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load: %v\n", err)
		os.Exit(1)
	}

	var loadErrors int
	for _, p := range pkgs {
		for _, e := range p.Errors {
			fmt.Fprintf(os.Stderr, "package %s: %v\n", p.PkgPath, e)
			loadErrors++
		}
	}

	// Map decl object ID -> stat
	stats := make(map[string]*callStat)

	getOrCreate := func(obj types.Object, fset *token.FileSet) *callStat {
		if !isInternalDecl(obj) {
			return nil
		}
		id := obj.Pkg().Path() + "|" + objDisplayName(obj)
		if s, ok := stats[id]; ok {
			return s
		}
		pos := obj.Pos()
		file := ""
		line := 0
		if pos != token.NoPos && fset != nil {
			file = fset.File(pos).Name()
			line = fset.File(pos).Line(pos)
		}
		s := &callStat{
			info: declInfo{
				pkgPath: obj.Pkg().Path(),
				name:    objDisplayName(obj),
				file:    file,
				line:    line,
			},
			distinctAll:   make(map[string]struct{}),
			distinctProd:  make(map[string]struct{}),
			seenPositions: make(map[string]struct{}),
		}
		stats[id] = s
		return s
	}

	// Build function range index per file for caller resolution.
	type fnRange struct {
		start, end token.Pos
		fn         *types.Func
	}
	fileRanges := make(map[string][]fnRange)

	for _, pkg := range pkgs {
		if pkg.TypesInfo == nil || pkg.Fset == nil {
			continue
		}
		for _, file := range pkg.Syntax {
			filePath := pkg.Fset.File(file.Pos()).Name()
			ast.Inspect(file, func(n ast.Node) bool {
				fd, ok := n.(*ast.FuncDecl)
				if !ok {
					return true
				}
				if fd.Name == nil {
					return true
				}
				obj := pkg.TypesInfo.Defs[fd.Name]
				fn, ok := obj.(*types.Func)
				if !ok {
					return true
				}
				end := fd.End()
				fileRanges[filePath] = append(fileRanges[filePath], fnRange{
					start: fd.Pos(),
					end:   end,
					fn:    fn,
				})
				// Ensure declaration is registered even with zero callers.
				getOrCreate(fn, pkg.Fset)
				return true
			})
		}
	}

	findCaller := func(fset *token.FileSet, pos token.Pos) *types.Func {
		filePath := fset.File(pos).Name()
		ranges := fileRanges[filePath]
		var best *types.Func
		var bestStart token.Pos
		for _, r := range ranges {
			if r.start <= pos && pos <= r.end && r.start >= bestStart {
				best = r.fn
				bestStart = r.start
			}
		}
		return best
	}

	resolveCallee := func(info *types.Info, call *ast.CallExpr) *types.Func {
		switch fun := call.Fun.(type) {
		case *ast.Ident:
			if obj, ok := info.Uses[fun].(*types.Func); ok {
				return obj
			}
		case *ast.SelectorExpr:
			switch obj := info.Uses[fun.Sel].(type) {
			case *types.Func:
				return obj
			}
		}
		return nil
	}

	totalCallsSeen := 0
	internalCallsMatched := 0

	for _, pkg := range pkgs {
		if pkg.TypesInfo == nil || pkg.Fset == nil {
			continue
		}
		for _, file := range pkg.Syntax {
			ast.Inspect(file, func(n ast.Node) bool {
				call, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				totalCallsSeen++
				fn := resolveCallee(pkg.TypesInfo, call)
				if fn == nil {
					return true
				}
				stat := getOrCreate(fn, pkg.Fset)
				if stat == nil {
					return true
				}
				internalCallsMatched++

				pos := call.Lparen
				if pos == token.NoPos {
					pos = call.Pos()
				}
				callerPos := pkg.Fset.Position(pos)
				callerIsTest := isTestFile(callerPos.Filename)
				caller := findCaller(pkg.Fset, pos)
				ck := callerKey(caller)

				stat.totalSites++
				stat.distinctAll[ck] = struct{}{}
				if !callerIsTest {
					stat.prodSites++
					stat.distinctProd[ck] = struct{}{}
				}
				return true
			})
		}
	}

	type ranked struct {
		id string
		*callStat
	}
	var all []ranked
	for id, s := range stats {
		all = append(all, ranked{id, s})
	}

	sortByTotal := func(a, b ranked) bool {
		if a.totalSites != b.totalSites {
			return a.totalSites > b.totalSites
		}
		if a.prodSites != b.prodSites {
			return a.prodSites > b.prodSites
		}
		return a.id < b.id
	}

	sort.Slice(all, func(i, j int) bool { return sortByTotal(all[i], all[j]) })

	fmt.Println("=== METHODOLOGY ===")
	fmt.Println("Metric: static direct call sites resolved by go/types (Uses on CallExpr fun).")
	fmt.Println("Each syntactic call expression counts once; builtins and dynamic/interface-only calls excluded.")
	fmt.Println("Distinct callers: unique enclosing function (package::Receiver.Method or package::Func).")
	fmt.Println("Production: call site in a non-_test.go file.")
	fmt.Printf("Packages loaded: %d; load errors: %d\n", len(pkgs), loadErrors)
	fmt.Printf("Total static call sites in repo: %d; to internal/ decls: %d\n", totalCallsSeen, internalCallsMatched)
	fmt.Printf("Internal functions/methods declared: %d\n", len(stats))

	fmt.Println("\n=== TOP 20 ALL GO (total static call sites) ===")
	fmt.Printf("%-5s %-7s %-7s %-7s %-7s %s\n", "Rank", "All", "Prod", "Callrs", "ProdCr", "Declaration @ location")
	for i, r := range all {
		if i >= 20 {
			break
		}
		fmt.Printf("%-5d %-7d %-7d %-7d %-7d %s.%s @ %s:%d\n",
			i+1, r.totalSites, r.prodSites, len(r.distinctAll), len(r.distinctProd),
			r.info.pkgPath, r.info.name, relRepo(r.info.file), r.info.line)
	}

	sort.Slice(all, func(i, j int) bool {
		ai, bj := all[i], all[j]
		if ai.prodSites != bj.prodSites {
			return ai.prodSites > bj.prodSites
		}
		return sortByTotal(ai, bj)
	})

	fmt.Println("\n=== TOP 20 PRODUCTION ONLY (non-_test.go call sites) ===")
	fmt.Printf("%-5s %-7s %-7s %-7s %-7s %s\n", "Rank", "Prod", "All", "ProdCr", "Callrs", "Declaration @ location")
	for i, r := range all {
		if i >= 20 {
			break
		}
		fmt.Printf("%-5d %-7d %-7d %-7d %-7d %s.%s @ %s:%d\n",
			i+1, r.prodSites, r.totalSites, len(r.distinctProd), len(r.distinctAll),
			r.info.pkgPath, r.info.name, relRepo(r.info.file), r.info.line)
	}

	// Winner by all-go metric
	sort.Slice(all, func(i, j int) bool { return sortByTotal(all[i], all[j]) })
	if len(all) == 0 {
		fmt.Println("No internal declarations found.")
		return
	}
	w := all[0]
	fmt.Println("\n=== WINNER (all Go static call sites) ===")
	fmt.Printf("Declaration: %s.%s\n", w.info.pkgPath, w.info.name)
	fmt.Printf("Path:line:  %s:%d\n", relRepo(w.info.file), w.info.line)
	fmt.Printf("All call sites: %d\n", w.totalSites)
	fmt.Printf("Distinct calling functions: %d\n", len(w.distinctAll))
	fmt.Printf("Production call sites: %d\n", w.prodSites)
	fmt.Printf("Distinct production callers: %d\n", len(w.distinctProd))

	if len(all) > 1 {
		fmt.Println("\n=== NEAREST COMPETITORS (all Go) ===")
		for i := 1; i <= 5 && i < len(all); i++ {
			c := all[i]
			fmt.Printf("#%d: %s.%s @ %s:%d — %d sites (%d prod), %d callers\n",
				i+1, c.info.pkgPath, c.info.name, relRepo(c.info.file), c.info.line,
				c.totalSites, c.prodSites, len(c.distinctAll))
		}
	}
}

