				if pos == token.NoPos {
					pos = call.Pos()
				}
				callerPos := pkg.Fset.Position(pos)
				posKey := fmt.Sprintf("%s:%d:%d", callerPos.Filename, callerPos.Line, callerPos.Column)
				if _, dup := stat.seenPositions[posKey]; dup {
