	fmt.Printf("Packages loaded: %d; load errors: %d\n", len(pkgs), loadErrors)
	fmt.Printf("Total static call sites in repo: %d; to internal/ decls: %d\n", totalCallsSeen, internalCallsMatched)
	fmt.Printf("Internal functions/methods declared: %d\n", len(stats))

	fmt.Println("\n=== TOP 20 ALL GO (total static call sites) ===")
	fmt.Printf("%-5s %-7s %-7s %-7s %-7s %s\n", "Rank", "All", "Prod", "Callrs", "ProdCr", "Declaration @ location")
	for i, r := range all {
		if i >= 20 {
			break
		}
		fmt.Printf("%-5d %-7d %-7d %-7d %-7d %s.%s @ %s:%d\n",
			i+1, r.totalSites, r.prodSites, len(r.distinctAll), len(r.distinctProd),
			r.info.pkgPath, r.info.name, relRepo(r.info.file), r.info.line)
	}

	sort.Slice(all, func(i, j int) bool {
		ai, bj := all[i], all[j]
		if ai.prodSites != bj.prodSites {
			return ai.prodSites > bj.prodSites
		}
		return sortByTotal(ai, bj)
	})

	fmt.Println("\n=== TOP 20 PRODUCTION ONLY (non-_test.go call sites) ===")
	fmt.Printf("%-5s %-7s %-7s %-7s %-7s %s\n", "Rank", "Prod", "All", "ProdCr", "Callrs", "Declaration @ location")
	for i, r := range all {
		if i >= 20 {
			break
		}
		fmt.Printf("%-5d %-7d %-7d %-7d %-7d %s.%s @ %s:%d\n",
			i+1, r.prodSites, r.totalSites, len(r.distinctProd), len(r.distinctAll),
			r.info.pkgPath, r.info.name, relRepo(r.info.file), r.info.line)
	}

	// Winner by all-go metric
	sort.Slice(all, func(i, j int) bool { return sortByTotal(all[i], all[j]) })
	if len(all) == 0 {
		fmt.Println("No internal declarations found.")
		return
	}
	w := all[0]
	fmt.Println("\n=== WINNER (all Go static call sites) ===")
	fmt.Printf("Declaration: %s.%s\n", w.info.pkgPath, w.info.name)
	fmt.Printf("Path:line:  %s:%d\n", relRepo(w.info.file), w.info.line)
